const writeFile=fs.writeFileSync.bind(fs);
fs.writeFileSync=function(file,data,...args){
 if(String(file).endsWith('.ipynb')&&fs.existsSync(file)){
  const previous=JSON.parse(fs.readFileSync(file,'utf8')),next=JSON.parse(data);
  if(JSON.stringify(previous.cells.map(c=>c.source))===JSON.stringify(next.cells.map(c=>c.source))){
   next.cells.forEach((cell,i)=>{if(cell.cell_type==='code'){cell.execution_count=previous.cells[i].execution_count;cell.outputs=previous.cells[i].outputs;}});
   data=JSON.stringify(next,null,2);
  }
 }
 return writeFile(file,data,...args);
};
