ml.forEach(([name,days,note,exercise,code,observation],i)=>{const file=`${pad(i+1)}_${i===0?'train_validation_test_split':slug(name).replace(/-/g,'_')}.ipynb`;const notebook={nbformat:4,nbformat_minor:5,metadata:{kernelspec:{display_name:'Python 3 (study)',language:'python',name:'python3'},language_info:{name:'python',version:'3.12'}},cells:[mdCell(`# ${name}\n\n## Learning Goal\n\n${note}\n\n## Minimal Prerequisites\n\nBasic Python arrays and functions. Run all cells in order; no API key or network data is required. Data are synthetic teaching fixtures, not empirical market evidence.\n\n## Guided Experiment\n\n${exercise}`),codeCell('import numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\n'),codeCell(code),mdCell(`## Expected Observations\n\n${observation}\n\n## Review Experiment\n\nBefore changing a parameter, write the direction you expect and why. Change only the parameter named in the guided experiment; rerun from a fresh kernel. Compare the observed result with your prediction. On a later review day, explain the code without reading the answers.\n\n## English Check Questions\n\n1. What quantity is this experiment estimating?\n2. What information is available at prediction time?\n3. Which observation would invalidate your conclusion?\n\n## Reference Answers\n\n1. ${note}\n2. Training inputs and their labels must be available before the relevant evaluation origin; preprocessing is fitted on training data only.\n3. ${observation}\n\n## Financial Connection\n\nTransfer the timing, metric or deployment contract to the five-day volatility Workbench. A toy experiment verifies mechanics, not trading profitability.\n\n## Sources\n\n${sources.ml.map(u=>'- '+u).join('\n')}\n\n[Return to study page](../Study%20topics/${slug(name)}.html)\n`)]};notebook.cells.forEach((c,j)=>c.id=`lesson-${i+1}-cell-${j+1}`);fs.writeFileSync('notebook/'+file,JSON.stringify(notebook,null,2));const body=`<h2>Short Explanation</h2><p>${esc(note)}</p><h2>Guided Experiment</h2><p>${esc(exercise)}</p><p><a href="../notebook/${file}">Open runnable notebook</a> · <a href="../notebook/README.md">One-time setup</a></p><p>Use 10–15 minutes for the explanation, 20–25 minutes for the experiment and 5–10 minutes for recall, about 45 minutes in all.</p><details><summary>Expected observation and interview script</summary><p>${esc(observation)}</p><p>${esc(note)}</p></details>${qa(`Explain ${name} to an interviewer.`,note,'What is the baseline and what would count as leakage?')}${qa('What can you claim from this experiment?',observation,'What real-data verification remains before deployment?')}<h2>Project Connection</h2><p>The Workbench uses the same timing and evaluation contracts. Synthetic fixtures are for learning and offline CI; replace them with versioned, licensed real data before making empirical investment claims.</p>`;const r=register(name,'ML',[],body,'ml');r.notebook=file;});
function diagram(flow){const labels=flow.split(' → ');return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 820 ${labels.length*72}" role="img" aria-label="${esc(flow)}">${labels.map((x,i)=>`<rect x="100" y="${i*72+4}" width="620" height="48" rx="8" fill="#e6f1f3" stroke="#77aab0"/><text x="410" y="${i*72+34}" text-anchor="middle" font-size="17" fill="#183449">${esc(x)}</text>${i<labels.length-1?`<text x="410" y="${i*72+70}" text-anchor="middle" fill="#146e78">↓</text>`:''}`).join('')}</svg>`;}
for(const [name,module,days,prompt,clarify,requirements,flow,decision,alternative,failure,follow,project] of design){const body=`<h2>Interview Prompt</h2><p>${esc(prompt)}</p><h2>Clarifying Questions</h2><p>${esc(clarify)}</p><h2>Functional and Non-Functional Requirements</h2><p>${esc(requirements)}</p><p>The numerical targets here are practice assumptions to negotiate with an interviewer, not measured project results.</p><h2>Architecture and Data Flow</h2>${diagram(flow)}<h2>Design Decisions and Alternatives</h2><p>${esc(decision)}</p><p>${esc(alternative)}</p><h2>Failure Scenarios</h2><p>${esc(failure)}</p>${module==='AI'?`<h2>AI Decision Checklist</h2><ul><li>Model: start with a measured task baseline; select by quality, latency, cost and permitted data handling.</li><li>Data and context: preserve source/version/permission scope; validate generated tool arguments outside the model.</li><li>Evaluation: use representative development and held-out cases, deterministic checks for numbers, human-calibrated review for open text.</li><li>Failures and oversight: bound calls and spend, distinguish failure from success, require real authorization for consequential actions.</li><li>Cost and latency: record tokens, retries, queue wait and critical-path stages; re-evaluate quality after optimization.</li></ul>`:''}<details><summary>Step-by-step interview script</summary><ol><li>I would first clarify: ${esc(clarify)}</li><li>I would propose this contract: ${esc(requirements)}</li><li>The main data flow is ${esc(flow)}.</li><li>The key decision is: ${esc(decision)}</li><li>The trade-off is: ${esc(alternative)}</li><li>I would test this failure: ${esc(failure)}</li><li>I would close by checking the design against the requirements and identifying the next measurement or implementation risk.</li></ol></details><h2>Follow-up Questions</h2><p>${esc(follow)}</p>${qa('How would you adapt the design if traffic increased tenfold?','I would identify the saturated resource from measured utilization and queueing, then consider partitioning, caching or additional workers while preserving ownership, idempotency and data consistency. I would not assume that multiplying replicas fixes a serialized dependency.','Which component in your drawing is the first bottleneck?')}<h2>Practice and Self-Review</h2><p>First learning day: 15 minutes explanation, 20 minutes drawing, 10 minutes follow-ups. Paired practice day: 30 minutes independent design and spoken explanation, 15 minutes comparing requirements, data flow, failure handling and trade-offs with this case. On buffer days change one constraint.</p><h2>Project Connection</h2><p>${esc(project)}</p>`;const r=register(name,module+' System Design',[],body,'design',module==='AI'?sources.ai:[]);r.mode=module;days.forEach(d=>slots[d-1].design.push(r));}
