const SLOTS=[['08:30–10:30','08:30–10:30'],['13:30–14:15','10:30–11:15'],['10:30–12:30','11:15–13:15'],['14:15–15:00','13:45–15:45'],['15:00–16:30','15:45–16:45','项目，1 小时'],['16:30–17:30','16:45–17:45'],['17:30–18:00','17:45–18:00','复盘，15 分钟']];
const retime=md=>{const lines=md.split('\n'),out=[],isRow=l=>/^\| \d{2}:\d{2}–\d{2}:\d{2} \|/.test(l);for(let i=0;i<lines.length;i++){if(!isRow(lines[i])){out.push(lines[i]);continue}const rows=[];while(i<lines.length&&isRow(lines[i]))rows.push(lines[i++]);i--;out.push(...rows.map(l=>{const t=l.slice(2,13),j=SLOTS.findIndex(x=>x[0]===t);if(j<0)throw Error('unknown time slot '+t);const [,to,label]=SLOTS[j];return [j,l.replace(/^\| [^|]+\| ([^|]+?) \|/,(m,what)=>`| ${to} | ${label||what} |`)]}).sort((a,b)=>a[0]-b[0]).map(x=>x[1]))}return out.join('\n')};
